sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var ga = new GlideAjax('setShortDescription');
    ga.addParam('sysparm_name', "shortDesc");
    ga.addParam('newValue', newValue);
    //    ga.addParam("shortDescript",shortDescript);
    ga.getXMLAnswer(answer);
}

function answer(response) {
    if (response == 1) {
        g_form.setValue('short_description', "priority is : " + 1);
    } else if (response == 2) {
        g_form.setValue('short_description', "priority is : " + 2);
    } else if (response == 3) {
        g_form.setValue('short_description', "priority is : " + 3);
    }
}
